    def setup_connections(self):
        """设置信号连接"""
        # 音频处理器信号
        self.audio_processor.pitch_detected.connect(self.on_pitch_detected)
        self.audio_processor.audio_level_updated.connect(self.on_audio_level_updated)
        self.audio_processor.recording_progress.connect(self.on_recording_progress)
        self.audio_processor.status_updated.connect(self.on_status_updated)
        
        # 🔥 验证信号连接
        print("🔥 信号连接已建立:")
        print(f"   🎯 pitch_detected -> on_pitch_detected: 已连接")
        print(f"   🎯 audio_level_updated -> on_audio_level_updated: 已连接")
        print(f"   🎯 recording_progress -> on_recording_progress: 已连接")
        print(f"   🎯 status_updated -> on_status_updated: 已连接")
        self.audio_processor.recording_finished.connect(self.on_recording_finished)
        self.audio_processor.error_occurred.connect(self.on_error_occurred)
    
    def toggle_main_recording(self):
        """切换主录音状态"""
        if not self.is_recording:
            self.start_recording()
        else:
            self.stop_recording()

    # ===== 本地音高解析：按钮与对话流（占位实现，先把按钮与流程接上） =====
    def open_local_pitch_dialog(self):
        """打开“本地音高解析”一级对话框：提供“纯人声 / 纯人声转化”分支。"""
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("本地音高解析")
            dlg.setStyleSheet("QDialog { background-color: #1f1f1f; color: white; }")
            v = QVBoxLayout(dlg)

            tip = QLabel("请选择要进行的操作")
            v.addWidget(tip)

            row = QHBoxLayout()
            btn_pure = QPushButton("纯人声")
            btn_convert = QPushButton("纯人声转化")
            row.addWidget(btn_pure)
            row.addWidget(btn_convert)
            v.addLayout(row)

            def _open_pure():
                dlg.accept()
                self._open_pure_vocal_mode_dialog()

            def _open_convert():
                dlg.accept()
                self._open_pure_vocal_convert_dialog()

            btn_pure.clicked.connect(_open_pure)
            btn_convert.clicked.connect(_open_convert)

            dlg.exec()
        except Exception as e:
            try:
                QMessageBox.warning(self, "本地音高解析", f"打开对话框失败:\n{e}")
            except Exception:
                print(f"[LocalPitch] open_local_pitch_dialog error: {e}")

    def _open_pure_vocal_mode_dialog(self):
        """纯人声子对话：提供“实时分析 / 一次性绘制”。"""
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("纯人声")
            dlg.setStyleSheet("QDialog { background-color: #1f1f1f; color: white; }")
            v = QVBoxLayout(dlg)
            v.addWidget(QLabel("选择分析方式"))

            row = QHBoxLayout()
            btn_realtime = QPushButton("实时分析")
            btn_onepass = QPushButton("一次性绘制")
            row.addWidget(btn_realtime)
            row.addWidget(btn_onepass)
            v.addLayout(row)

            def _choose_file_and_realtime():
                try:
                    if PYQT_VERSION == 6:
                        file_path, _ = QFileDialog.getOpenFileName(
                            self, "选择音频文件", str(self.save_base_dir),
                            "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                        )
                    else:
                        file_path, _ = QFileDialog.getOpenFileName(
                            self, "选择音频文件", str(self.save_base_dir),
                            "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                        )
                except Exception:
                    file_path = ""
                if file_path:
                    dlg.accept()
                    try:
                        # 调用占位入口（若后续提供真实实现将自动委托）
                        _enter_local_file_realtime_mode(self, file_path)
                    except Exception as _e:
                        try:
                            QMessageBox.information(self, "本地音高解析", f"入口已就绪，但功能尚未完全实现。\n文件: {file_path}\n异常: {_e}")
                        except Exception:
                            print(f"[LocalPitch] realtime invoke error: {_e}")

            def _one_pass_render():
                try:
                    if PYQT_VERSION == 6:
                        file_path, _ = QFileDialog.getOpenFileName(
                            self, "选择音频文件（一次性绘制）", str(self.save_base_dir),
                            "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                        )
                    else:
                        file_path, _ = QFileDialog.getOpenFileName(
                            self, "选择音频文件（一次性绘制）", str(self.save_base_dir),
                            "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                        )
                except Exception:
                    file_path = ""
                if file_path:
                    dlg.accept()
                    try:
                        # 启动离线一次性绘制流程
                        if hasattr(self, '_start_offline_onepass'):
                            return self._start_offline_onepass(file_path)
                        # 回退：若未打补丁，提示占位
                        QMessageBox.information(self, "一次性绘制", "该功能将很快提供：会对整个文件进行分析并一次性绘制结果。")
                    except Exception:
                        print("[LocalPitch] one-pass placeholder invoked.")

            btn_realtime.clicked.connect(_choose_file_and_realtime)
            btn_onepass.clicked.connect(_one_pass_render)

            dlg.exec()
        except Exception as e:
            try:
                QMessageBox.warning(self, "纯人声", f"打开子对话失败:\n{e}")
            except Exception:
                print(f"[LocalPitch] _open_pure_vocal_mode_dialog error: {e}")

    def _open_pure_vocal_convert_dialog(self):
        """纯人声转化：选择输入文件与输出目录，支持默认目录与自命名，并执行人声/伴奏分离。"""
        try:
            # 1) 准备默认输入/输出目录（持久化）
            try:
                settings = QSettings("MindEcho", "IntegratedRecorder")
            except Exception:
                settings = None
            base_dir = Path(getattr(self, 'save_base_dir', Path.cwd()))
            in_default = base_dir / "VocalConvertInput"
            out_default = base_dir / "VocalConvertOutput"
            try:
                if settings:
                    last_in = settings.value("vocal_convert_input_dir", str(in_default))
                    last_out = settings.value("vocal_convert_output_dir", str(out_default))
                    in_default = Path(str(last_in))
                    out_default = Path(str(last_out))
            except Exception:
                pass
            for p in (in_default, out_default):
                try:
                    Path(p).mkdir(parents=True, exist_ok=True)
                except Exception:
                    pass

            # 2) 选择源文件
            try:
                if PYQT_VERSION == 6:
                    src_file, _ = QFileDialog.getOpenFileName(
                        self, "选择需要转化的音频文件", str(in_default),
                        "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                    )
                else:
                    src_file, _ = QFileDialog.getOpenFileName(
                        self, "选择需要转化的音频文件", str(in_default),
                        "音频文件 (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.wma);;所有文件 (*)"
                    )
            except Exception:
                src_file = ""
            if not src_file:
                return

            # 3) 选择输出目录
            try:
                if PYQT_VERSION == 6:
                    out_dir = QFileDialog.getExistingDirectory(self, "选择保存文件夹", str(out_default))
                else:
                    out_dir = QFileDialog.getExistingDirectory(self, "选择保存文件夹", str(out_default))
            except Exception:
                out_dir = ""
            if not out_dir:
                return

            # 4) 自定义文件名对话框（人声/伴奏）
            try:
                src_stem = Path(src_file).stem
            except Exception:
                src_stem = "output"

            name_dlg = QDialog(self)
            name_dlg.setWindowTitle("设置导出文件名")
            name_dlg.setStyleSheet("QDialog { background-color: #1f1f1f; color: white; }")
            v = QVBoxLayout(name_dlg)
            desc = QLabel("请选择分离算法，并设置输出文件名。\n提示：Demucs 质量更好（可用GPU），首次使用会下载模型；Spleeter 轻量快速但质量略逊。")
            desc.setWordWrap(True)
            v.addWidget(desc)
            # 算法选择
            algo_row = QHBoxLayout(); algo_row.addWidget(QLabel("分离算法:"))
            algo_combo = QComboBox(); algo_combo.addItems([
                "Demucs（推荐，支持GPU，质量较好）",
                "Spleeter（轻量，速度快）"
            ])
            algo_row.addWidget(algo_combo); v.addLayout(algo_row)
            # Demucs 模型选择与简介（仅在选择 Demucs 时显示）
            demucs_model_row = QHBoxLayout()
            demucs_model_label = QLabel("Demucs 模型:")
            demucs_model_row.addWidget(demucs_model_label)
            demucs_model_combo = QComboBox()
            demucs_model_combo.addItems([
                "htdemucs_ft", "htdemucs", "mdx_extra_q", "mdx_extra", "mdx", "mdx_q"
            ])
            demucs_model_row.addWidget(demucs_model_combo)
            v.addLayout(demucs_model_row)
            # Demucs 质量/速度预设
            demucs_preset_row = QHBoxLayout()
            demucs_preset_label = QLabel("Demucs 预设:")
            demucs_preset_row.addWidget(demucs_preset_label)
            demucs_preset_combo = QComboBox()
            demucs_preset_combo.addItems(["速度优先", "标准", "高质量"])
            try:
                demucs_preset_combo.setCurrentIndex(1)
            except Exception:
                pass
            demucs_preset_row.addWidget(demucs_preset_combo)
            v.addLayout(demucs_preset_row)
            demucs_tip = QLabel("")
            demucs_tip.setWordWrap(True)
            demucs_tip.setStyleSheet("color:#aaaaaa;")
            v.addWidget(demucs_tip)
            # 简介映射
            _demucs_desc = {
                "htdemucs_ft": "Hybrid Transformer Demucs（微调版）：音质最佳，更耗显存/时间。",
                "htdemucs": "Hybrid Transformer Demucs：高质量，较 ft 略轻。",
                "mdx_extra_q": "MDX Extra（量化）：更小更快，音质略降。",
                "mdx_extra": "MDX Extra：质量/速度折中，人声鲁棒性佳。",
                "mdx": "MDX 基线：轻量、兼容性好。",
                "mdx_q": "MDX 量化：更轻更快，音质进一步让步。",
            }
            def _update_demucs_tip():
                try:
                    name = demucs_model_combo.currentText()
                    demucs_tip.setText(f"说明：{_demucs_desc.get(name, '')}")
                except Exception:
                    pass
            demucs_model_combo.currentIndexChanged.connect(lambda _i: _update_demucs_tip())
            _update_demucs_tip()
            # 检测 Spleeter 可用性（本地或外部桥接）
            try:
                import sys, importlib, os
                from pathlib import Path as _Path
                from PyQt5.QtCore import Qt  # type: ignore
                # 本地可用：Python<=3.10 且已安装 spleeter
                local_py_ok = (sys.version_info[0] == 3 and sys.version_info[1] <= 10)
                local_ok = False
                if local_py_ok:
                    try:
                        importlib.import_module('spleeter')
                        local_ok = True
                    except Exception:
                        local_ok = False
                # 外部桥接：优先 MIND_ECHO_SPLEETER_PY，其次自动探测仓库内 venv
                bridge_py_env = os.environ.get('MIND_ECHO_SPLEETER_PY')
                bridge_py = bridge_py_env
                if not bridge_py or not os.path.isfile(bridge_py):
                    try:
                        repo_tools = _Path(__file__).resolve().parent.parent.parent / 'tools'
                        for rel in [
                            '.venv_spleeter310/Scripts/python.exe',
                            '.venv_spleeter39/Scripts/python.exe',
                        ]:
                            cand = repo_tools / rel
                            if cand.exists():
                                bridge_py = str(cand)
                                break
                    except Exception:
                        pass
                bridge_ok = bool(bridge_py and os.path.isfile(bridge_py))
                if bridge_ok and (not bridge_py_env):
                    # 写入当前进程环境，便于后续桥接调用
                    os.environ['MIND_ECHO_SPLEETER_PY'] = bridge_py

                if local_ok:
                    tip = QLabel("已检测到：当前环境可直接使用 Spleeter。")
                    tip.setStyleSheet("color:#7CFC00;")  # 亮绿
                    tip.setWordWrap(True)
                    v.addWidget(tip)
                elif bridge_ok:
                    tip = QLabel("已检测到：本环境不支持 Spleeter，但发现外部 Spleeter 环境，将通过桥接使用（无需切换主环境）。")
                    tip.setStyleSheet("color:#ffcc00;")
                    tip.setWordWrap(True)
                    # 这里应添加刚创建的 tip 到布局
                    v.addWidget(tip)
                    # 注：环境噪声采集入口仅保留在主界面“设置”中，此处不再展示
            except Exception:
                # 探测异常时，静默回退，不阻断后续 UI
                pass

            # 声部分离选择（2/4/5 声部），供后续逻辑使用
            stems_row = QHBoxLayout(); stems_row.addWidget(QLabel("声部分离:"))
            stems_combo = QComboBox(); stems_combo.addItems([
                "2 声部（人声+伴奏）",
                "4 声部（人声+鼓+贝斯+其他）",
                "5 声部（人声+鼓+贝斯+钢琴+其他）",
            ])
            try:
                stems_combo.setCurrentIndex(0)
            except Exception:
                pass
            stems_row.addWidget(stems_combo); v.addLayout(stems_row)
            # 算法/声部联动提示
            note_lbl = QLabel("")
            note_lbl.setWordWrap(True)
            note_lbl.setStyleSheet("color:#ffcc00;")
            v.addWidget(note_lbl)
            # 当选择 4/5 声部时，如当前为 Demucs，则自动切换到 Spleeter
            def _on_stems_changed(idx: int):
                try:
                    if idx in (1, 2) and algo_combo.currentIndex() == 0:  # 选了 4/5 且算法=Demucs
                        algo_combo.setCurrentIndex(1)  # 切到 Spleeter
                        note_lbl.setText("提示：Demucs 仅支持 2 声部，已根据您的 4/5 声部选择自动切换为 Spleeter。")
                    elif idx == 0:
                        # 恢复选择 2 声部时清空提示
                        note_lbl.setText("")
                except Exception:
                    pass
            stems_combo.currentIndexChanged.connect(_on_stems_changed)
            # 当切回 Demucs 时，若当前声部为 4/5，则强制改为 2 声部
            def _on_algo_changed(idx: int):
                try:
                    if idx == 0 and stems_combo.currentIndex() != 0:  # Demucs + 非2声部
                        stems_combo.setCurrentIndex(0)
                        note_lbl.setText("提示：Demucs 仅支持 2 声部（已自动改为 2）。如需 4/5 声部，请选择 Spleeter。")
                    elif idx == 1:
                        # 选择 Spleeter 时清空提示（交互更干净）
                        note_lbl.setText("")
                    # 切换 Demucs 模型/预设控件可见性
                    show_demucs = (idx == 0)
                    for w in (demucs_model_label, demucs_model_combo, demucs_tip, demucs_preset_label, demucs_preset_combo):
                        try:
                            w.setVisible(show_demucs)
                        except Exception:
                            pass
                except Exception:
                    pass
            algo_combo.currentIndexChanged.connect(_on_algo_changed)
            # 初始可见性
            try:
                _show_dm = (algo_combo.currentIndex() == 0)
                for w in (demucs_model_label, demucs_model_combo, demucs_tip, demucs_preset_label, demucs_preset_combo):
                    w.setVisible(_show_dm)
            except Exception:
                pass

            # 导出格式选择
            fmt_row = QHBoxLayout(); fmt_row.addWidget(QLabel("导出格式:"))
            fmt_combo = QComboBox(); fmt_combo.addItems([
                "原始 WAV（无压缩，体积最大，兼容性最佳）",
                "FLAC 无损压缩（推荐，体积≈30%~70%）",
                "OGG 有损高压缩（体积≈5%~15%，适合分享）",
                "MP3（有损，高兼容；建议VBR品质2）",
                "M4A AAC（有损，移动端/苹果友好）",
                "OPUS（有损，高压缩/高音质）",
                "M4A ALAC（无损，苹果无损）",
                "AIFF（无压缩/PCM，专业音频）",
                "WavPack（无损压缩，.wv）"
            ])
            try:
                fmt_combo.setCurrentIndex(1)  # 默认选择 FLAC
            except Exception:
                pass
            fmt_row.addWidget(fmt_combo); v.addLayout(fmt_row)
            fmt_tip = QLabel("说明：\n- WAV 无压缩，体积最大；\n- FLAC/M4A ALAC 为无损压缩（推荐 FLAC，苹果生态可选 ALAC）；\n- OGG/MP3/AAC/OPUS 为有损压缩（OPUS/MP3 兼顾音质与体积，AAC 移动端友好）。")
            fmt_tip.setWordWrap(True)
            v.addWidget(fmt_tip)
            v.addWidget(QLabel("输出文件名（无需扩展名）："))
            row1 = QHBoxLayout(); row1.addWidget(QLabel("人声文件名:"))
            vocal_edit = QLineEdit(f"{src_stem}_人声")
            row1.addWidget(vocal_edit); v.addLayout(row1)
            row2 = QHBoxLayout(); row2.addWidget(QLabel("伴奏文件名:"))
            acc_edit = QLineEdit(f"{src_stem}_伴奏")
            row2.addWidget(acc_edit); v.addLayout(row2)
            # —— 多声部（4/5）额外文件名 ——
            row_dr = QHBoxLayout(); lbl_dr = QLabel("鼓 文件名:"); dr_edit = QLineEdit(f"{src_stem}_鼓"); row_dr.addWidget(lbl_dr); row_dr.addWidget(dr_edit); v.addLayout(row_dr)
            row_bs = QHBoxLayout(); lbl_bs = QLabel("贝斯 文件名:"); bs_edit = QLineEdit(f"{src_stem}_贝斯"); row_bs.addWidget(lbl_bs); row_bs.addWidget(bs_edit); v.addLayout(row_bs)
            row_ot = QHBoxLayout(); lbl_ot = QLabel("其他 文件名:"); ot_edit = QLineEdit(f"{src_stem}_其他"); row_ot.addWidget(lbl_ot); row_ot.addWidget(ot_edit); v.addLayout(row_ot)
            row_pi = QHBoxLayout(); lbl_pi = QLabel("钢琴 文件名:"); pi_edit = QLineEdit(f"{src_stem}_钢琴"); row_pi.addWidget(lbl_pi); row_pi.addWidget(pi_edit); v.addLayout(row_pi)
            # 默认隐藏，按声部选择联动显示
            def _toggle_multistem_name_rows(idx: int):
                try:
                    show4 = (idx in (1, 2))
                    show5 = (idx == 2)
                    for w in (lbl_dr, dr_edit): w.setVisible(show4)
                    for w in (lbl_bs, bs_edit): w.setVisible(show4)
                    for w in (lbl_ot, ot_edit): w.setVisible(show4)
                    for w in (lbl_pi, pi_edit): w.setVisible(show5)
                except Exception:
                    pass
            _toggle_multistem_name_rows(stems_combo.currentIndex())
            stems_combo.currentIndexChanged.connect(_toggle_multistem_name_rows)
            row3 = QHBoxLayout()
            btn_ok = QPushButton("开始转换")
            btn_cancel = QPushButton("取消")
            row3.addWidget(btn_ok); row3.addWidget(btn_cancel)
            v.addLayout(row3)

            def _on_ok():
                name_dlg.accept()
            btn_ok.clicked.connect(_on_ok)
            btn_cancel.clicked.connect(name_dlg.reject)
            if name_dlg.exec() != QDialog.DialogCode.Accepted:
                return

            vocals_name = (vocal_edit.text() or "人声").strip()
            acc_name = (acc_edit.text() or "伴奏").strip()
            algo_text = algo_combo.currentText()
            algo_choice = 'demucs' if 'Demucs' in algo_text else 'spleeter'
            selected_demucs_model = demucs_model_combo.currentText() if algo_choice == 'demucs' else None
            # 预设: fast/standard/quality
            if algo_choice == 'demucs':
                preset_txt = (demucs_preset_combo.currentText() or "标准").strip()
                if preset_txt.startswith("速度"):
                    selected_demucs_preset = 'fast'
                elif preset_txt.startswith("高质"):
                    selected_demucs_preset = 'quality'
                else:
                    selected_demucs_preset = 'standard'
            else:
                selected_demucs_preset = None
            stems_text = stems_combo.currentText()
            if stems_text.startswith('4'):
                stems = 4
            elif stems_text.startswith('5'):
                stems = 5
            else:
                stems = 2
            # 若选择 Demucs，则强制 2 声部
            if algo_choice == 'demucs':
                stems = 2
            # 读取多声部自定义名称
            drums_name = bass_name = other_name = piano_name = None
            if stems in (4, 5):
                drums_name = (dr_edit.text() or f"{src_stem}_鼓").strip()
                bass_name = (bs_edit.text() or f"{src_stem}_贝斯").strip()
                other_name = (ot_edit.text() or f"{src_stem}_其他").strip()
                if stems == 5:
                    piano_name = (pi_edit.text() or f"{src_stem}_钢琴").strip()
            fmt_text = fmt_combo.currentText()
            if fmt_text.startswith("原始 WAV"):
                export_format = 'wav'
            elif fmt_text.startswith("FLAC"):
                export_format = 'flac'
            elif fmt_text.startswith("OGG"):
                export_format = 'ogg'
            elif fmt_text.startswith("MP3"):
                export_format = 'mp3'
            elif fmt_text.startswith("M4A AAC"):
                export_format = 'm4a'
            elif fmt_text.startswith("OPUS"):
                export_format = 'opus'
            elif fmt_text.startswith("M4A ALAC"):
                export_format = 'alac'
            elif fmt_text.startswith("AIFF"):
                export_format = 'aiff'
            elif fmt_text.startswith("WavPack"):
                export_format = 'wv'
            else:
                export_format = 'flac'

            # 5) 持久化最近目录
            try:
                if settings:
                    settings.setValue("vocal_convert_input_dir", str(Path(src_file).parent))
                    settings.setValue("vocal_convert_output_dir", str(out_dir))
            except Exception:
                pass

            # 6) 启动转化流程
            self._start_vocal_conversion(src_file, out_dir, vocals_name, acc_name, algo_choice, export_format, stems, demucs_model=selected_demucs_model, drums_name=drums_name, bass_name=bass_name, piano_name=piano_name, other_name=other_name, demucs_preset=selected_demucs_preset)
        except Exception as e:
            try:
                QMessageBox.warning(self, "纯人声转化", f"操作失败:\n{e}")
            except Exception:
                print(f"[LocalPitch] _open_pure_vocal_convert_dialog error: {e}")

    # —— 纯人声转化：启动工作线程与进度 UI ——
    def _start_vocal_conversion(self, src_file: str, out_dir: str, vocals_name: str, acc_name: str, algo_choice: str, export_format: str, stems: int = 2, *, demucs_model: str | None = None, drums_name: str | None = None, bass_name: str | None = None, piano_name: str | None = None, other_name: str | None = None, demucs_preset: str | None = None):
        try:
            prog = _OnePassProgressDialog(self, title="纯人声转化 - 处理进度")
            prog.set_message("准备中…")
            worker = _VocalSeparationWorker(src_file, out_dir, vocals_name, acc_name, algo_choice, export_format, stems, demucs_model=demucs_model, drums_name=drums_name, bass_name=bass_name, piano_name=piano_name, other_name=other_name, demucs_preset=demucs_preset)

            def _on_prog(p):
                prog.set_progress(p)
            def _on_msg(m):
                prog.set_message(m)
            def _on_ok(payload):
                try:
                    prog.set_progress(100)
                    prog.set_message("完成")
                    v_path = payload.get('vocals_path', '')
                    a_path = payload.get('acc_path', '')
                    engine = payload.get('engine', '未知')
                    try:
                        QMessageBox.information(self, "纯人声转化", f"已完成\n引擎: {engine}\n人声: {v_path}\n伴奏: {a_path}")
                    except Exception:
                        print(f"[VocalConvert] done: engine={engine}, vocals={v_path}, acc={a_path}")
                finally:
                    try:
                        prog.accept()
                    except Exception:
                        pass
            def _on_fail(err):
                try:
                    QMessageBox.critical(self, "纯人声转化", f"失败: {err}")
                except Exception:
                    print(f"[VocalConvert] failed: {err}")
                try:
                    prog.reject()
                except Exception:
                    pass
            def _on_cancel():
                try:
                    worker.cancel()
                except Exception:
                    pass
                try:
                    prog.reject()
                except Exception:
                    pass

            worker.progress.connect(_on_prog)
            worker.message.connect(_on_msg)
            worker.finished_ok.connect(_on_ok)
            worker.failed.connect(_on_fail)
            prog.btn_cancel.clicked.connect(_on_cancel)

            worker.start()
            prog.show(); prog.exec()
        finally:
            try:
                if 'worker' in locals() and worker.isRunning():
                    worker.cancel(); worker.wait(200)
            except Exception:
                pass
    
    def start_recording(self):
        """开始录音"""
        try:
            # 设置参数
            sample_rate = int(self.sample_rate_combo.currentText())
            should_save = self.save_checkbox.isChecked()
            
            # 生成文件名（允许中英文自定义）
            if should_save:
                timestamp = time.strftime("%Y%m%d_%H%M%S")
                raw_name = (self.filename_prefix.currentText() or "").strip()
                # 清洗：保留常见合法字符；对 Windows 不允许的字符进行替换为下划线
                # 允许：中文、英文、数字、空格、- _ () [] {}
                try:
                    import re
                    # 先替换 Windows 非法字符 <>:"/\\|?* 为下划线
                    cleaned = re.sub(r"[<>:\"/\\\\|?*]", "_", raw_name)
                    # 去除首尾点和空格，避免 Win 末尾点/空格问题
                    cleaned = cleaned.strip(" .")
                    # 防御：若为空则回退到默认前缀
                    if not cleaned:
                        cleaned = "recording"
                except Exception:
                    cleaned = raw_name or "recording"
                filename = f"{cleaned}_{timestamp}"
            else:
                filename = None
            
            # 更新处理器参数
            self.audio_processor.sample_rate = sample_rate
            
            # 启动录音
            if self.audio_processor.start_recording(filename, should_save):
                self.is_recording = True
                self.is_analyzing = True  # 录音时也是分析状态
                
                print(f"✅ 录音已启动: 文件={filename}, 保存={should_save}")
                
                # 更新UI
                self.main_record_button.setText("停止录音")
                self.main_record_button.setStyleSheet("""
                    QPushButton {
                        background-color: #D32F2F;
                        border: 2px solid #F44336;
                        border-radius: 8px;
                        padding: 12px 24px;
                        font-size: 14px;
                        font-weight: bold;
                        color: white;
                    }
                    QPushButton:hover {
                        background-color: #F44336;
                        border-color: #EF5350;
                    }
                """)
                
                self.pause_button.setEnabled(True)
                # 每次开始录音时，确保按钮文本为“暂停”，避免继承上次状态
                try:
                    self.pause_button.setText("暂停")
                except Exception:
                    pass
                
                # 清除统计数据
                self.total_pitches_detected = 0
                self.recording_duration = 0
                
                # 🔥 立即更新检测统计显示为初始状态
                self.detection_count_label.setText("检测点数: 0")
                self.detection_rate_label.setText("检测频率: 0/秒")
                print("🔥 检测统计已重置为初始状态")
                
                # 清除可视化
                self.visualizer.clear_data()
                
                # 开始时间追踪（支持断续音调曲线）
                self.visualizer.start_time_tracking()
                # 若伴奏模式开启则启动伴奏播放 + 锁定伴奏长度为时间轴最大长度
                self._maybe_start_backing_playback()
                try:
                    if getattr(self, 'backing_mode', 'off') in ('accompaniment','both') and \
                       getattr(self, 'backing_sample_rate', None) and \
                       getattr(self, 'backing_pcm_accompaniment', None) is not None:
                        dur = len(self.backing_pcm_accompaniment)/float(self.backing_sample_rate)
                        # 主窗口层锁定
                        self._backing_axis_locked = True
                        self._backing_axis_length = float(dur)
                        # 同步到可视化器自身，确保 set_max_history_time 内部缩短保护生效
                        try:
                            if hasattr(self.visualizer, '_backing_axis_locked'):
                                self.visualizer._backing_axis_locked = True
                            else:
                                setattr(self.visualizer, '_backing_axis_locked', True)
                            self.visualizer._backing_axis_length = float(dur)
                            print(f"🔗 同步可视化锁定长度 {dur:.2f}s -> visualizer")
                        except Exception as _e_vis_lock:
                            print(f"⚠️ 可视化锁定同步失败: {_e_vis_lock}")
                        self._sync_time_axis_to_accompaniment(dur, reason="recording_start_lock", force=True)
                        try:
                            if hasattr(self.visualizer, 'update_scrollbars'):
                                self.visualizer.update_scrollbars()
                        except Exception:
                            pass
                        print(f"🔒 伴奏时间轴锁定 {dur:.2f}s (录音开始)")
                    else:
                        # 无伴奏模式：解锁
                        self._backing_axis_locked = False
                        if hasattr(self, '_backing_axis_length'):
                            delattr(self, '_backing_axis_length')
                        # 解除可视化器锁
                        try:
                            if hasattr(self.visualizer, '_backing_axis_locked'):
                                self.visualizer._backing_axis_locked = False
                            if hasattr(self.visualizer, '_backing_axis_length'):
                                delattr(self.visualizer, '_backing_axis_length')
                        except Exception:
                            pass
                except Exception as _sync_rec_e:
                    print(f"⚠️ 录音开始伴奏轴锁定失败: {_sync_rec_e}")
                # 自动弹出伴奏/原唱控制窗口（一次性）
                # 需求：不开启伴奏模式时不要自动打开伴奏控制窗口
                try:
                    if getattr(self, 'backing_mode', 'off') != 'off':
                        self._backing_paused = False
                        self.open_backing_control_window()
                    else:
                        print("ℹ️ 录音开始：伴奏模式=off，不自动弹出伴奏控制窗口")
                except Exception as _e_show2:
                    print(f"⚠️ 录音开始阶段自动弹出伴奏控制窗口失败: {_e_show2}")
                
        except Exception as e:
            QMessageBox.critical(self, "录音错误", f"启动录音失败: {e}")
    
    def stop_recording(self):
        """停止录音"""
        try:
            self.audio_processor.stop_recording()
            self.is_recording = False
            # 录音结束时同步结束分析状态，防止伴奏误判仍在分析
            self.is_analyzing = False
            # 若伴奏锁定存在，录音结束后仍允许浏览全长，但去除“锁”使用户可自定义最大长度
            try:
                if getattr(self, '_backing_axis_locked', False):
                    print("🔓 录音结束解除伴奏锁 (保留可视化当前长度)")
                self._backing_axis_locked = False
                if hasattr(self, '_backing_axis_length'):
                    delattr(self, '_backing_axis_length')
                if hasattr(self, 'visualizer') and self.visualizer is not None:
                    if hasattr(self.visualizer, '_backing_axis_locked'):
                        self.visualizer._backing_axis_locked = False
                    if hasattr(self.visualizer, '_backing_axis_length'):
                        delattr(self.visualizer, '_backing_axis_length')
            except Exception:
                pass
            # 停止伴奏播放（与录音联动）
            self._stop_backing_playback()
            # 重置暂停按钮文本为“暂停”，并禁用
            try:
                self.pause_button.setText("暂停")
            except Exception:
                pass
            
            # 停止时间追踪
            self.visualizer.stop_time_tracking()
            # 解除伴奏时间轴锁定
            try:
                if getattr(self, '_backing_axis_locked', False):
                    print("🔓 解除伴奏时间轴锁定 (录音结束)")
                self._backing_axis_locked = False
            except Exception:
                pass
            
            # 更新UI
            self.main_record_button.setText("开始录音分析")
            self.main_record_button.setStyleSheet("""
                QPushButton {
                    background-color: #2E7D32;
                    border: 2px solid #4CAF50;
                    border-radius: 8px;
                    padding: 12px 24px;
                    font-size: 14px;
                    font-weight: bold;
                    color: white;
                }
                QPushButton:hover {
                    background-color: #388E3C;
                    border-color: #66BB6A;
                }
            """)
            
            self.pause_button.setEnabled(False)
            
        except Exception as e:
            QMessageBox.critical(self, "录音错误", f"停止录音失败: {e}")
    
    def pause_recording(self):
        """暂停/恢复录音"""
        try:
            if self.pause_button.text() == "暂停":
                # 执行暂停
                ok = True
                if hasattr(self, 'audio_processor') and self.audio_processor:
                    ok = bool(self.audio_processor.pause_recording())
                if ok:
                    # 标记全局暂停，供检测/显示层早退
                    self.is_paused = True
                    try:
                        self._set_backing_paused(True)
                    except Exception:
                        pass
                    # 可视化冻结：停止时间推进 + 禁止新增点
                    # 冻结可视化时间推进
                    if hasattr(self, 'visualizer') and hasattr(self.visualizer, 'pause_time_tracking'):
                        self.visualizer.pause_time_tracking()
                    if hasattr(self, 'visualizer'):
                        try:
                            self.visualizer._external_paused = True  # add_pitch_data 会检查该标志
                        except Exception:
                            pass
                    # 清空当前音高显示
                    try:
                        self.current_pitch_label.setText("当前音高: -- Hz")
                        self.current_note_label.setText("当前音符: --")
                    except Exception:
                        pass
                    self.pause_button.setText("继续")
                    if hasattr(self, 'status_label'):
                        self.status_label.setText("已暂停，点击继续")
                else:
                    QMessageBox.warning(self, "暂停失败", "当前未在录音，或暂停操作不可用。")
            else:
                # 执行恢复
                ok = True
                if hasattr(self, 'audio_processor') and self.audio_processor:
                    ok = bool(self.audio_processor.resume_recording())
                if ok:
                    # 恢复标志
                    self.is_paused = False
                    try:
                        self._set_backing_paused(False)
                    except Exception:
                        pass
                    # 重置检测频率平滑基线（防止跨越暂停）
                    try:
                        self._detection_rate_smoothing_active = True
                        self._detection_rate_smoothing_start = time.time()
                        self._detection_rate_baseline_pitches = int(getattr(self, 'total_pitches_detected', 0))
                    except Exception:
                        pass
                    if hasattr(self, 'visualizer') and hasattr(self.visualizer, 'resume_time_tracking'):
                        self.visualizer.resume_time_tracking()
                    if hasattr(self, 'visualizer'):
                        try:
                            self.visualizer._external_paused = False
                        except Exception:
                            pass
                    self.pause_button.setText("暂停")
                    if hasattr(self, 'status_label'):
                        self.status_label.setText("录音继续")
                else:
                    QMessageBox.warning(self, "继续失败", "无法继续，可能未处于暂停状态。")
        except Exception as e:
            QMessageBox.critical(self, "暂停/继续错误", str(e))
    
    def toggle_monitoring(self):
        """切换监听功能（优化版：只音频回放，不分析）"""
        try:
            if not hasattr(self, 'is_monitoring'):
                self.is_monitoring = False
                
            if not self.is_monitoring:
                # 启动优化监听功能
                success = self.start_monitoring()
                if success:
                    self.is_monitoring = True
                    # 通过可视化器访问监听按钮
                    if hasattr(self.visualizer, 'monitor_button'):
                        self.visualizer.monitor_button.setText("关闭监听")
                        self.visualizer.monitor_button.setChecked(True)
                    print("🎧 优化监听功能已启动")
            else:
                # 关闭监听功能
                self.stop_monitoring()
                self.is_monitoring = False
                # 通过可视化器访问监听按钮
                if hasattr(self.visualizer, 'monitor_button'):
                    self.visualizer.monitor_button.setText("开启监听")
                    self.visualizer.monitor_button.setChecked(False)
                print("🎧 监听功能已关闭")
                
        except Exception as e:
            print(f"❌ 切换监听功能失败: {e}")
            
    def start_monitoring(self):
        """启动监听功能（优化版：只音频回放，不分析）"""
        try:
            # 检查是否有耳机连接
            if self.check_headphone_connection():
                print("🎧 检测到耳机连接，启动优化监听功能")
                
                # 🔥 开始优化的音频监听（48kHz + 128样本块 + 智能降噪）
                if self.audio_processor.start_audio_monitoring():
                    self.system_status_label.setText("状态: 监听中（优化版）")
                    return True
                else:
                    print("❌ 启动优化音频监听失败")
                    return False
            else:
                print("⚠️  未检测到耳机，建议连接耳机以避免啸叫")
                # 询问用户是否继续
                from PyQt6.QtWidgets import QMessageBox
                reply = QMessageBox.question(
                    self, 
                    "监听模式提醒", 
                    "未检测到耳机连接。\n\n在没有耳机的情况下使用优化监听功能可能会产生啸叫声。\n\n是否继续启动监听？\n\n✨ 新功能特性:\n• 48kHz高质量采样\n• 128样本超低延迟\n• 智能降噪处理\n• 实时延迟监测",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No
                )
                
                if reply == QMessageBox.StandardButton.Yes:
                    if self.audio_processor.start_audio_monitoring():
                        self.system_status_label.setText("状态: 监听中(无耳机)")
                        return True
                    else:
                        print("❌ 启动音频监听失败")
                        return False
                else:
                    return False
                    
        except Exception as e:
            print(f"❌ 启动监听功能失败: {e}")
            return False
    
    def stop_monitoring(self):
        """停止监听功能"""
        try:
            if hasattr(self.audio_processor, 'stop_audio_monitoring'):
                self.audio_processor.stop_audio_monitoring()
                
            self.system_status_label.setText("状态: 就绪")
            print("🎧 监听功能已停止")
            # 监听结束后也不应继续播放伴奏
            if not (self.is_recording or self.is_analyzing):
                self._stop_backing_playback()
            
        except Exception as e:
            print(f"❌ 停止监听功能失败: {e}")
    
