    def _apply_ui_params_for_mode(self, mode, config=None):
        """根据性能模式调整可视化节流与平滑参数（仅影响显示层）。"""
        try:
            from src.audio_processing.performance_manager import PerformanceMode
        except Exception:
            PerformanceMode = None
        try:
            if PerformanceMode and mode == PerformanceMode.HIGH_PERFORMANCE:
                # 更高刷新频率、稍弱平滑
                self._vis_min_interval_sec = 0.012
                self._plot_freq_alpha = 0.45
                self._plot_freq_history_maxlen = 25
                self._plot_savgol_win = 7
                self._plot_savgol_poly = 2
            elif PerformanceMode and mode == PerformanceMode.BALANCED:
                # 默认均衡
                self._vis_min_interval_sec = 0.016
                self._plot_freq_alpha = 0.35
                self._plot_freq_history_maxlen = 33
                self._plot_savgol_win = 9
                self._plot_savgol_poly = 2
            else:
                # QUIET 或未知：更强平滑、降低刷新频率
                self._vis_min_interval_sec = 0.022
                self._plot_freq_alpha = 0.22
                self._plot_freq_history_maxlen = 41
                self._plot_savgol_win = 11
                self._plot_savgol_poly = 2
        except Exception:
            # 容错：保持当前参数
            pass

    def _on_performance_mode_changed(self, new_mode, config):
        """性能模式变更回调：联动更新显示参数"""
        try:
            self._apply_ui_params_for_mode(new_mode, config)
            # 可选：清理绘图缓存，避免窗口参数巨变导致瞬时抖动
            if isinstance(getattr(self, '_plot_freq_history', None), list) and len(self._plot_freq_history) > self._plot_freq_history_maxlen:
                self._plot_freq_history = self._plot_freq_history[-self._plot_freq_history_maxlen:]
        except Exception:
            pass

    def on_pitch_detected(self, pitch_data):
        """音高检测回调（支持断续音调曲线模式）"""
        try:
            # 暂停时完全停止后续检测处理（不累积统计，不绘制，不更新时间）
            if getattr(self, 'is_paused', False) or getattr(self, '_backing_paused', False):
                return
            # 更新统计
            self.total_pitches_detected += 1
            
            # 🔥 立即更新检测统计显示
            self.detection_count_label.setText(f"检测点数: {self.total_pitches_detected}")
            
            # 统一检测频率显示
            self.detection_rate_label.setText(self._compute_and_format_detection_rate())
            
            # 🎯 调试输出检测统计更新（受开关和节流控制）
            if getattr(self, 'debug_flags', {}).get('detection_log', False):
                if hasattr(self, '_detection_debug_counter'):
                    self._detection_debug_counter += 1
                else:
                    self._detection_debug_counter = 1
                # 每3秒最多打印一次
                now_ts = time.time()
                if not hasattr(self, '_last_detection_log_time'):
                    self._last_detection_log_time = 0.0
                if now_ts - self._last_detection_log_time > 3.0:
                    print(f"🎯 检测统计更新#{self._detection_debug_counter}: 总检测数={self.total_pitches_detected}")
                    self._last_detection_log_time = now_ts
            
            # 更新当前音高信息
            frequency = pitch_data.get('frequency', 0)  # 平滑后的
            raw_frequency = pitch_data.get('raw_frequency', None)
            note_info = pitch_data.get('note_info', {})
            has_pitch = pitch_data.get('has_pitch', frequency > 0)
            
            if has_pitch and frequency > 0:
                # 记录平滑频率用于原逻辑
                self.current_frequency = frequency
                # 增加调试：显示 raw vs smooth（仅首次若开启）
                if raw_frequency is not None:
                    if not hasattr(self, '_raw_smooth_debug'):
                        self._raw_smooth_debug = 0
                    self._raw_smooth_debug += 1
                    if self._raw_smooth_debug <= 10:
                        if not (callable(getattr(self, '_should_suppress_audio_debug', None)) and self._should_suppress_audio_debug()):
                            print(f"🎯 UI接收频率: raw={raw_frequency:.2f}Hz smooth={frequency:.2f}Hz diff={abs(raw_frequency-frequency):.2f}Hz")
                
                if note_info:
                    note_name = note_info.get('note_name', '--')
                    octave = note_info.get('octave', '')
                    cents = note_info.get('cents', 0)
                    self.current_note = f"{note_name}{octave}"
                    
                    self.current_note_label.setText(
                        f"当前音符: {note_name}{octave} ({cents:+.0f} cents)"
                    )
                else:
                    self.current_note = "--"
                    self.current_note_label.setText("当前音符: --")
            else:
                # 无音高时显示"静音"状态，但不清除上一个音符信息
                # 这样用户可以看到最后检测到的音符和当前的静音状态
                if not hasattr(self, '_silence_counter'):
                    self._silence_counter = 0
                self._silence_counter += 1
                
                # 每100帧更新一次静音状态显示
                if self._silence_counter % 100 == 0:
                    audio_rms = pitch_data.get('audio_rms', 0)
                    self.current_note_label.setText(f"当前音符: -- (静音中, RMS: {audio_rms:.4f})")
            
            # 发送到可视化器（录音分析模式下显示音调线，纯监听模式跳过）
            should_show_pitch_line = (
                getattr(self.audio_processor, 'is_recording', False) or  # 录音模式
                (self.audio_processor.is_global_monitoring_active and not getattr(self.audio_processor, 'is_monitoring_only', False))  # 监听+录音模式
            )
            
            if should_show_pitch_line:
                # 绘制节流：限制最短重绘间隔，降低Matplotlib重绘负载
                now_wall = time.time()
                if (now_wall - getattr(self, '_vis_last_draw_wall', 0.0)) < getattr(self, '_vis_min_interval_sec', 0.018):
                    # 仍更新文本/统计，但跳过绘制，平衡CPU与流畅度
                    pass
                else:
                    base_payload = dict(pitch_data)
                    # 可选：使用SciPy作轻量平滑以减少细抖动（仅影响显示）
                    try:
                        f = float(base_payload.get('frequency', 0.0))
                    except Exception:
                        f = 0.0
                    if f > 0:
                        try:
                            # 维护少量历史
                            self._plot_freq_history.append(f)
                            maxlen = int(getattr(self, '_plot_freq_history_maxlen', 33))
                            if len(self._plot_freq_history) > maxlen:
                                # 限制长度，避免不必要内存与计算
                                self._plot_freq_history = self._plot_freq_history[-maxlen:]
                            f_smooth = None
                            # SciPy Savitzky-Golay（7~11点小窗，二次多项式）
                            base_win = int(getattr(self, '_plot_savgol_win', 9))
                            base_poly = int(getattr(self, '_plot_savgol_poly', 2))
                            if len(self._plot_freq_history) >= 5:
                                try:
                                    from scipy.signal import savgol_filter
                                    # 窗口长度须为奇数且<=长度；以base_win为目标
                                    win_target = base_win if base_win > 0 else 9
                                    # 不能超过现有长度，且需要奇数
                                    max_allowed = len(self._plot_freq_history)
                                    if max_allowed % 2 == 0:
                                        max_allowed -= 1
                                    win = max(5, min(win_target, max_allowed))
                                    if win % 2 == 0:
                                        win = max(5, win - 1)
                                    poly = max(2, min(base_poly, 4))
                                    sm = savgol_filter(self._plot_freq_history, window_length=win, polyorder=poly, mode='interp')
                                    f_smooth = float(sm[-1])
                                except Exception:
                                    f_smooth = None
                            # 回退：EMA
                            if f_smooth is None:
                                if hasattr(self, '_plot_freq_prev'):
                                    f_smooth = self._plot_freq_alpha * f + (1.0 - self._plot_freq_alpha) * float(getattr(self, '_plot_freq_prev', f))
                                else:
                                    f_smooth = f
                            self._plot_freq_prev = float(f_smooth)
                            base_payload['frequency'] = float(f_smooth)
                        except Exception:
                            # 平滑失败时直接使用原值
                            base_payload = dict(pitch_data)
                    # 录音分析模式：显示音调线
                    try:
                        if base_payload.get('_epoch') is None:
                            base_payload['_epoch'] = int(getattr(self, '_record_epoch', 0))
                    except Exception:
                        pass
                    self.visualizer.add_pitch_data(base_payload)
                    self._vis_last_draw_wall = now_wall
            else:
                # 纯监听模式：跳过音调线绘制
                if getattr(self, '_pitch_precision_debug_counter', 0) <= 5:
                    print("🎧 纯监听模式：跳过音调线绘制")
            
            # 🔥 音高精度验证调试（前50次检测）
            self._pitch_precision_debug_counter = getattr(self, '_pitch_precision_debug_counter', 0) + 1
            if self._pitch_precision_debug_counter == 1:
                print("🎵 开始音高精度验证...")
            if self._pitch_precision_debug_counter <= 50 and has_pitch and frequency > 0:
                if raw_frequency is not None:
                    print(f"🎵 音高精度#{self._pitch_precision_debug_counter}: raw={raw_frequency:.3f}Hz smooth={frequency:.3f}Hz")
                else:
                    print(f"🎵 音高精度#{self._pitch_precision_debug_counter}: 输入={frequency:.3f}Hz")
            
        except Exception as e:
            print(f"处理音高数据错误: {e}")
    
    def on_audio_level_updated(self, level):
        """音频电平更新"""
        try:
            if getattr(self, 'is_paused', False) or getattr(self, '_backing_paused', False):
                return  # 暂停状态不刷新电平，保持视觉静止
            # 转换为百分比
            level_percent = min(100, int(level * 1000))
            self.audio_level_bar.setValue(level_percent)
            self.audio_level_label.setText(f"音频电平: {level_percent}%")
            
        except Exception as e:
            print(f"更新音频电平错误: {e}")
    
    def on_recording_progress(self, duration):
        """录音进度更新"""
        try:
            if getattr(self, 'is_paused', False) or getattr(self, '_backing_paused', False):
                return  # 暂停不更新，保持冻结
            eff = self.get_effective_recording_time(float(duration))
            self.recording_duration = max(0.0, float(eff))
        except Exception:
            self.recording_duration = float(duration)
    
    def on_status_updated(self, status):
        """状态更新"""
        self.system_status_label.setText(f"状态: {status}")
    
    def on_recording_finished(self, filename, analysis_results):
        """录音完成"""
        try:
            # 复位状态标志与伴奏
            self.is_recording = False
            self.is_analyzing = False
            try:
                self._stop_backing_playback()
            except Exception as _se:
                print(f"停止伴奏播放失败: {_se}")

            # 安全获取统计
            total_pitches = 0
            duration = 0.0
            try:
                if isinstance(analysis_results, dict):
                    total_pitches = int(analysis_results.get('total_pitches', 0))
                    duration = float(analysis_results.get('recording_duration', 0.0))
            except Exception as _pe:
                print(f"解析分析结果失败: {_pe}")

            # 更新内部总数（若需要后续 UI 刷新）
            self.total_pitches_detected = max(self.total_pitches_detected, total_pitches)
            self.recording_duration = max(self.recording_duration, duration)

            # 更新按钮 / UI 状态
            try:
                if hasattr(self, 'main_record_button'):
                    self.main_record_button.setText("开始录音分析")
                    self.main_record_button.setEnabled(True)
                if hasattr(self, 'pause_button'):
                    self.pause_button.setEnabled(False)
                if hasattr(self, 'listenback_button'):
                    self.listenback_button.setEnabled(True)
            except Exception as _be:
                print(f"更新按钮状态失败: {_be}")

            # 系统状态标签
            try:
                self.system_status_label.setText("状态: 就绪")
            except Exception:
                pass

            # 构建与显示信息
            try:
                if filename:
                    message = f"录音已保存: {os.path.basename(filename)}\n"
                else:
                    message = "分析完成（未保存录音）\n"
                message += f"录音时长: {duration:.1f}秒\n"
                message += f"检测到音高点: {total_pitches}个\n"
                if duration > 0:
                    detection_rate = total_pitches / max(duration, 1e-6)
                    message += f"平均检测频率: {detection_rate:.1f}次/秒"
                QMessageBox.information(self, "录音完成", message)
            except Exception as _ie:
                print(f"显示录音完成信息失败: {_ie}")

        except Exception as e:
            print(f"处理录音完成事件错误: {e}")

    # ================= 新增：统一时长与检测频率辅助 =================
    def get_effective_recording_time(self, fallback: float) -> float:
        """伴奏模式用伴奏播放位置其余用回调值；暂停时冻结。"""
        try:
            if getattr(self, 'is_paused', False) or getattr(self, '_backing_paused', False):
                return float(getattr(self, 'recording_duration', fallback))
            # 伴奏模式判断：存在 backing_play_position + backing_sample_rate
            if hasattr(self, 'backing_play_position') and hasattr(self, 'backing_sample_rate') and self.backing_sample_rate:
                pos_sec = float(self.backing_play_position) / float(self.backing_sample_rate)
                if pos_sec >= 0:
                    return pos_sec
            return float(fallback)
        except Exception:
            return float(fallback)

    def _compute_and_format_detection_rate(self) -> str:
        """计算检测频率（暂停返回 --，恢复初期平滑）。"""
        try:
            if getattr(self, 'is_paused', False) or getattr(self, '_backing_paused', False):
                return "检测频率: --"
            dur = float(getattr(self, 'recording_duration', 0.0))
            if dur <= 0:
                return "检测频率: 计算中..."
            total = int(getattr(self, 'total_pitches_detected', 0))
            if total == 0:
                return "检测频率: 0/秒"
            # 平滑窗口
            if getattr(self, '_detection_rate_smoothing_active', False):
                window = float(getattr(self, '_detection_rate_smoothing_window', 2.5))
                start = float(getattr(self, '_detection_rate_smoothing_start', time.time()))
                elapsed = time.time() - start
                baseline = int(getattr(self, '_detection_rate_baseline_pitches', total))
                inc = max(0, total - baseline)
                if elapsed < window:
                    rate = inc / window
                    if elapsed > 0.3:
                        raw_rate = inc / max(elapsed, 0.3)
                        rate = min(rate, raw_rate)
                    return f"检测频率: {rate:.1f}/秒"
                else:
                    self._detection_rate_smoothing_active = False
            rate = total / max(dur, 1e-3)
            return f"检测频率: {rate:.1f}/秒"
        except Exception:
            return "检测频率: 计算中..."
    
    def on_error_occurred(self, error_msg):
        """错误处理"""
        try:
            QMessageBox.critical(self, "错误", error_msg)
        except RecursionError:
            print(f"[ERROR](recursion) {error_msg}")
        except Exception as _dlg_e:
            print(f"[ERROR] {error_msg} (dialog failed: {_dlg_e})")
        try:
            if hasattr(self, 'system_status_label') and self.system_status_label:
                self.system_status_label.setText(f"错误: {error_msg}")
        except Exception:
            pass
    
